window.products.push({"id":240195,"name":"Northcore Wall Mounted Bamboo Tide Clock","category":"homeandappliances","retail price":19.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71QCRYy7LCL._AC_UL1200_.jpg","description":"bamboo frame Set into natural bamboo with a laser etched face, our Northcore tide clocks are designed to provide a guide to tide times at your selected location. Simply refer to your local tide chart, coordinate and set your clock to the high or low tide, insert an AA battery (not included) and the clock will rotate every 12 hours and 25 minutes giving you an indication as to the state of your local tide as well as showing hours remaining until high or low water. The clock is approximately 25 x 25 cm in size and looks stunning on any home, office or work place wall. It's the ideal accessory or gift for surfers, sailors, beach walkers and many more. Location adjustable, Requires 1 x AA Battery","images":["https://m.media-amazon.com/images/I/71QCRYy7LCL._AC_UL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Northcore","source_asin":"B01JOZ7072","category_path":"Home & Kitchen"},"sku":"BM-240195","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01JOZ7072","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01JOZ7072","price_pending":true,"merchant_ready":false});
